"use client";

import { useId, useState } from "react";

const COLORS = ["bg-red-500", "bg-orange-500", "bg-yellow-500", "bg-lime-500", "bg-green-500"];

export function PasswordInputTailwind() {
  const id = useId();
  const [value, setValue] = useState("");
  const [show, setShow] = useState(false);
  const rules = [value.length >= 8, /[a-z]/.test(value) && /[A-Z]/.test(value), /\d/.test(value), /[^A-Za-z0-9\s]/.test(value)];
  const score = value ? rules.filter(Boolean).length : 0;
  return (
    <div className="w-full max-w-sm space-y-2 text-zinc-100">
      <label htmlFor={id} className="text-sm font-medium">Password</label>
      <div className="flex h-11 items-center rounded-xl border border-zinc-800 bg-zinc-900 focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/25">
        <input id={id} type={show ? "text" : "password"} value={value} onChange={(e) => setValue(e.target.value)} className="h-full flex-1 bg-transparent px-3.5 outline-none" />
        <button type="button" aria-pressed={show} aria-label={show ? "Hide password" : "Show password"} onClick={() => setShow(!show)} className="mr-1.5 rounded-lg px-2 py-1 text-xs text-zinc-400 hover:bg-zinc-800">{show ? "Hide" : "Show"}</button>
      </div>
      <div aria-hidden="true" className="grid grid-cols-4 gap-1.5">
        {[0, 1, 2, 3].map((i) => (
          <span key={i} className="h-1.5 overflow-hidden rounded-full bg-zinc-800">
            <span className={`block h-full origin-left transition-transform duration-300 ${COLORS[score]} ${score > i ? "scale-x-100" : "scale-x-0"}`} />
          </span>
        ))}
      </div>
    </div>
  );
}
